const { chromium } = require('playwright');
const path = require('path');

(async () => {
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage();
  const filePath = 'file://' + path.resolve(__dirname, 'poster.html');
  await page.goto(filePath, { waitUntil: 'networkidle' });
  // Wait extra for fonts and charts to render
  await page.waitForTimeout(3000);

  const poster = await page.$('#poster');
  await poster.screenshot({ path: path.resolve(__dirname, 'final_poster.png'), type: 'png' });
  await browser.close();
  console.log('Saved final_poster.png');
})();
